const tiposPermitidos = new Set(['kpi', 'tabela', 'barras']);

const registros = $input.all()
  .map((item) => item.json)
  .filter((item) => item && Object.keys(item).length > 0)
  // somente seções ativas (registro sem o campo 'ativo' é tratado como ativo)
  .filter((item) => item.ativo === undefined || item.ativo === null || item.ativo === true)
  .sort((a, b) => {
    const oa = Number(a.ordem ?? 0);
    const ob = Number(b.ordem ?? 0);
    if (oa !== ob) return oa - ob;
    return Number(a.id) - Number(b.id);
  });

const secoes = [];
const erros = [];

for (const registro of registros) {
  const id = String(registro.id ?? '').trim();
  const nome = String(registro.nome ?? '').trim();
  const descricao = String(registro.descricao ?? '').trim();
  const ordem = Number(registro.ordem ?? 0);
  // 'config' (jsonb) chega como objeto; mantém compatibilidade com string e com a coluna legada 'conteudo'.
  const bruto = registro.config ?? registro.conteudo;

  try {
    if (!id || !nome) {
      throw new Error('id e nome sao obrigatorios');
    }

    if (typeof bruto === 'string' && bruto.trim().startsWith('<')) {
      throw new Error('config legado em HTML; converta o registro para a especificacao JSON v1');
    }

    const configuracao = typeof bruto === 'string' ? JSON.parse(bruto) : bruto;

    if (!configuracao || typeof configuracao !== 'object' || Array.isArray(configuracao)) {
      throw new Error('config deve ser um objeto JSON');
    }

    const componentesOriginais = configuracao.componentes;
    if (!Array.isArray(componentesOriginais) || componentesOriginais.length === 0) {
      throw new Error('componentes deve possuir ao menos um item');
    }

    const ids = new Set();
    const componentes = componentesOriginais.map((componente, indice) => {
      if (!componente || typeof componente !== 'object' || Array.isArray(componente)) {
        throw new Error(`componente ${indice + 1} invalido`);
      }

      const componenteId = String(componente.id ?? '').trim();
      const tipo = String(componente.tipo ?? '').trim().toLowerCase();

      if (!componenteId) throw new Error(`componente ${indice + 1} sem id`);
      if (ids.has(componenteId)) throw new Error(`id de componente duplicado: ${componenteId}`);
      if (!tiposPermitidos.has(tipo)) throw new Error(`tipo nao suportado: ${tipo}`);
      if (!componente.consulta || typeof componente.consulta !== 'object') {
        throw new Error(`componente ${componenteId} sem consulta valida`);
      }

      ids.add(componenteId);

      const largura = Math.min(12, Math.max(3, Number(componente.largura) || 6));
      const normalizado = { ...componente, id: componenteId, tipo, largura };

      if (tipo === 'kpi' && !String(componente.campo_valor ?? '').trim()) {
        throw new Error(`componente ${componenteId} precisa de campo_valor`);
      }

      if (tipo === 'tabela' && (!Array.isArray(componente.colunas) || componente.colunas.length === 0)) {
        throw new Error(`componente ${componenteId} precisa de colunas`);
      }

      if (tipo === 'barras' && (!componente.campo_categoria || !componente.campo_valor)) {
        throw new Error(`componente ${componenteId} precisa de campo_categoria e campo_valor`);
      }

      return normalizado;
    });

    secoes.push({
      id,
      nome,
      descricao,
      ordem,
      versao: Number(configuracao.versao) || 1,
      componentes
    });
  } catch (error) {
    erros.push({
      id: id || null,
      nome: nome || null,
      erro: error.message
    });
  }
}

return [{
  json: {
    sucesso: true,
    versao_contrato: 1,
    total: secoes.length,
    secoes,
    erros,
    endpoints: {
      dados: '/webhook/dashboard_dados'
    }
  }
}];
